hl.bind(mainMod .. " + S", hl.dsp.exec_cmd("slurp -d | grim -g - ~/Pictures/Screenshots/shot-$(date +%F_%H-%M-%S).png"))

hl.bind(mainMod .. " + SHIFT + S", hl.dsp.exec_cmd("slurp -d | grim -g - ~/Pictures/Screenshots/shot-$(date +%F_%H-%M-%S).png"))

