hl.on("hyprland.start", function()
    hl.exec_cmd("~/.config/hypr/scripts/cool_down.sh")
    hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP DBUS_SESSION_BUS_ADDRESS")
    hl.exec_cmd("systemctl --user import-environment WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
    hl.exec_cmd("/usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1")
    hl.exec_cmd("hyprpaper")
    hl.exec_cmd("hypridle")
    hl.exec_cmd("waybar")
    hl.exec_cmd("nm-applet --indicator")
    hl.exec_cmd("blueman-applet")
    hl.exec_cmd("mpvpaper -o \"loop --input-ipc-server=/tmp/mpv-wallpaper-socket\" eDP-1 ~/something_just_like_this.webm")
    hl.exec_cmd("~/.config/hypr/scripts/wallpaper-audio.sh")
end)

hl.on("config.reloaded", function()
    hl.exec_cmd("swaybg -m fill -i ~/.config/hypr/wallpapers/57.jpg")
end)

